package cn.zhuatech.procureagent.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class SourcingRecommendationApprovalServiceTest{private final SourcingRecommendationApprovalService s=new SourcingRecommendationApprovalService();@Test void awardsGovernedRecommendation(){var r=s.assess(new SourcingRecommendationApprovalService.Request("S1",true,true,true,true,true,true,true,3,10,true,true));assertThat(r.decision()).isEqualTo(SourcingRecommendationApprovalService.Decision.AWARD);}@Test void negotiatesPriceAndContract(){var r=s.assess(new SourcingRecommendationApprovalService.Request("S2",true,true,true,true,true,true,true,20,10,false,true));assertThat(r.actions()).hasSize(2);}@Test void blocksUnfairSourcing(){var r=s.assess(new SourcingRecommendationApprovalService.Request("S3",false,false,false,false,false,false,false,3,10,true,false));assertThat(r.blockers()).hasSize(8);}}
